CREATE DATABASE IF NOT EXISTS bill_analyzer CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bill_analyzer;
CREATE TABLE IF NOT EXISTS categories(category_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,keywords JSON NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bills(bill_id BIGINT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,provider_name VARCHAR(255),bill_date DATE,bill_time TIME,amount DECIMAL(12,2),currency VARCHAR(10) NOT NULL DEFAULT 'INR',bill_number VARCHAR(100),payment_mode VARCHAR(50),source_file VARCHAR(500) NOT NULL,ocr_confidence DECIMAL(5,2),notes TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_bills_category FOREIGN KEY(category_id) REFERENCES categories(category_id),UNIQUE KEY uq_bill_source_file(source_file),INDEX idx_bills_date(bill_date),INDEX idx_bills_category(category_id),INDEX idx_bills_date_category(bill_date,category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS weekly_summary(week_id VARCHAR(8) NOT NULL,week_start_date DATE NOT NULL,week_end_date DATE NOT NULL,category_id INT NOT NULL,bill_count INT NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'INR',generated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(week_id,category_id),CONSTRAINT fk_weekly_category FOREIGN KEY(category_id) REFERENCES categories(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS monthly_summary(month_id CHAR(7) NOT NULL,category_id INT NOT NULL,bill_count INT NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'INR',generated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(month_id,category_id),CONSTRAINT fk_monthly_category FOREIGN KEY(category_id) REFERENCES categories(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
